'use strict';
// Operational views derive their figures from the same records as the patient list.
for(const entry of state.logs)if(entry.actor==='Hệ thống demo')entry.actor='Hệ thống';
function operationalData(){
 const active=state.patients.filter(p=>p.status!=='Hoàn tất');
 const finished=state.patients.filter(p=>p.status==='Hoàn tất');
 const overdue=active.filter(p=>p.wait>30);
 const urgent=active.filter(p=>p.priority==='Cao');
 const pending=active.filter(p=>!state.decisions.some(d=>d.patientId===p.id));
 const average=active.length?Math.round(active.reduce((n,p)=>n+p.wait,0)/active.length):0;
 const grouped=new Map();
 for(const p of active){if(!grouped.has(p.department))grouped.set(p.department,[]);grouped.get(p.department).push(p);}
 const rooms=[...grouped].map(([name,patients])=>({name,patients,count:patients.length,waiting:patients.filter(p=>p.status==='Đang chờ').length,average:Math.round(patients.reduce((n,p)=>n+p.wait,0)/patients.length),longest:Math.max(...patients.map(p=>p.wait))})).sort((a,b)=>b.average-a.average);
 const attention=active.filter(p=>p.wait>30||p.priority==='Cao').sort((a,b)=>b.wait-a.wait);
 return {total:state.patients.length,active,finished,overdue,urgent,pending,average,rooms,attention};
}
function operationalMetric(label,value,unit,ico,color,foot,action){return `<button class="ops-metric ${color}" ${action?`data-ops="${action}"`:'data-action="patients"'}><div class="between"><span>${label}</span>${circle(ico,color)}</div><strong>${value}<small>${unit}</small></strong><div class="metric-caption">${foot}${icon('arrow')}</div></button>`;}
function operationalDonut(){const colors={'Đang chờ':'#2f75e8','Đang khám':'#13a18a','Đang làm CLS':'#e5a635','Hoàn tất':'#8770d2'};const total=state.patients.length;let offset=0;const parts=Object.entries(colors).map(([label,color])=>({label,color,count:state.patients.filter(p=>p.status===label).length}));const gradient=parts.map(p=>{let start=offset;offset+=total?p.count/total*100:0;return `${p.color} ${start}% ${offset}%`;}).join(',');return `<div class="donut-wrap"><div class="donut" style="background:${total?`conic-gradient(${gradient})`:'#edf1f7'}" role="img" aria-label="Phân bổ ${total} hồ sơ theo trạng thái"><div class="donut-center"><strong>${total}</strong><small>hồ sơ tiếp nhận</small></div></div><div class="donut-legend">${parts.map(p=>`<div><i class="dot" style="color:${p.color}"></i><span>${p.label}</span><b>${p.count}</b><small>${total?Math.round(p.count/total*100):0}%</small></div>`).join('')}</div></div>`;}
function operationalWaitChart(){const active=operationalData().active;const groups=[{name:'0–15 phút',min:0,max:15,color:'#51bfa4'},{name:'16–30 phút',min:16,max:30,color:'#4e8fe9'},{name:'31–60 phút',min:31,max:60,color:'#e6b45b'},{name:'Trên 60 phút',min:61,max:Infinity,color:'#dd7a8e'}].map(g=>({...g,count:active.filter(p=>p.wait>=g.min&&p.wait<=g.max).length}));const max=Math.max(5,...groups.map(g=>g.count));return `<svg class="ops-wait-chart" viewBox="0 0 560 195" role="img" aria-label="Số hồ sơ theo thời gian chờ: ${groups.map(g=>g.name+': '+g.count).join(', ')}">${[0,1,2,3,4].map(i=>{let y=150-i*31;return `<path d="M32 ${y}H548" stroke="#eaf0f7"/><text x="10" y="${y+4}">${Math.round(max*i/4)}</text>`;}).join('')}${groups.map((g,i)=>{let height=g.count/max*122;let x=62+i*125;return `<rect x="${x}" y="${150-height}" width="66" height="${height}" rx="6" fill="${g.color}"/><text class="bar-number" x="${x+33}" y="${140-height}" text-anchor="middle">${g.count}</text><text x="${x+33}" y="176" text-anchor="middle">${g.name}</text>`;}).join('')}</svg>`;}
function operationalRooms(){const d=operationalData();return `<div class="ops-room-list">${d.rooms.slice(0,6).map((r,i)=>`<button class="ops-room" data-ops-dept="${esc(r.name)}"><span class="room-symbol">${icon(['stethoscope','flask','monitor','hospital'][i%4])}</span><span class="room-label"><strong>${esc(r.name)}</strong><small>${r.count} người bệnh · ${r.waiting} đang chờ</small></span><span class="room-load"><strong>${r.average}<small> phút</small></strong>${badge(r.average>30?'Chờ lâu':'Trong ngưỡng',r.average>30?'amber':'green',false)}</span>${icon('chevron')}</button>`).join('')||'<div class="empty">Chưa có hồ sơ đang xử lý.</div>'}</div>`;}
function operationalResources(){const d=operationalData();return `<div class="table-wrap"><table><thead><tr><th>Phòng chức năng</th><th>Đang xử lý</th><th>Đang chờ</th><th>Chờ TB</th></tr></thead><tbody>${d.rooms.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${r.count}</td><td>${r.waiting}</td><td>${badge(r.average+' phút',r.average>30?'amber':'green',false)}</td></tr>`).join('')||'<tr><td colspan="4" class="table-empty">Chưa có hồ sơ đang xử lý.</td></tr>'}</tbody></table></div>`;}
function operationalAlerts(){const d=operationalData();return d.overdue.sort((a,b)=>b.wait-a.wait).map(p=>`<div class="list-row">${circle('clock',p.wait>60?'red':'amber')}<div><strong>${esc(p.name)} · ${p.wait} phút</strong><small>${esc(p.department)} · ${p.id}</small></div>${badge(p.priority,priorityColor(p.priority),false)}</div>`).join('')||'<div class="empty">Không có người bệnh chờ quá 30 phút.</div>';}
function operationalDashboard(){const d=operationalData();const donePercent=d.total?Math.round(d.finished.length/d.total*100):0;return uiHeader(state.role==='Điều phối viên'?'Bảng điều phối ngoại trú':'Tổng quan khoa khám bệnh','Theo dõi lượt khám, hàng đợi và những hồ sơ cần xử lý.')+`<section class="ops-context"><div class="ops-context-title">${circle('hospital')}<div><strong>Khoa Khám bệnh</strong><span>Tiếp nhận & điều phối ngoại trú <i>•</i> Ngày hồ sơ 14/10/2026</span></div></div><div class="ops-context-actions">${button('Tiếp nhận người bệnh','new-patient','primary','plus')}${button('Danh sách bệnh nhân','patients','','users')}</div></section><div class="ops-metrics">${operationalMetric('Tổng lượt tiếp nhận',d.total,'','users','',`${d.active.length} hồ sơ đang xử lý`,'all')}${operationalMetric('Hoàn tất khám',d.finished.length,'','check','green',`${donePercent}% tổng lượt tiếp nhận`,'finished')}${operationalMetric('Thời gian chờ trung bình',d.average,'phút','clock','teal','Tính trên hồ sơ chưa hoàn tất','all')}${operationalMetric('Chờ quá 30 phút',d.overdue.length,'','alert','red',`${d.overdue.filter(p=>p.wait>60).length} người bệnh chờ trên 60 phút`,'overdue')}</div><div class="ops-main-grid"><section class="card ops-attention"><div class="card-head"><div><h2>Danh sách cần xử lý <span class="inline-count">${d.attention.length}</span></h2><p>Ưu tiên hồ sơ chờ lâu và người bệnh mức ưu tiên cao.</p></div><button class="link" data-ops="attention">Xem tất cả ${icon('arrow')}</button></div><div class="table-wrap"><table class="ops-attention-table"><thead><tr><th>Người bệnh</th><th>Phòng hiện tại</th><th>Chờ</th><th></th></tr></thead><tbody>${d.attention.slice(0,5).map((p,i)=>`<tr><td><button class="patient-name" data-patient="${p.id}">${avatar(p.name,i)}<span><strong>${esc(p.name)}</strong><small>${p.id} · ${p.age} tuổi</small></span></button></td><td><strong>${esc(p.department)}</strong><small>${esc(p.room)} · ${p.status}</small></td><td><span class="ops-wait ${p.wait>60?'red':'amber'}">${icon('clock')} ${p.wait} phút</span></td><td><button class="icon-btn" data-transfer="${p.id}" title="Điều phối ${esc(p.name)}" aria-label="Điều phối ${esc(p.name)}">${icon('transfer')}</button></td></tr>`).join('')||'<tr><td colspan="4" class="table-empty">Không có hồ sơ cần ưu tiên xử lý.</td></tr>'}</tbody></table></div><div class="ops-table-footer">${icon('info')} Hiển thị ${Math.min(5,d.attention.length)} hồ sơ · Sắp xếp theo thời gian chờ giảm dần.</div></section>${card('Tình hình phòng chức năng',operationalRooms(),moreLink('resources','Chi tiết'),'ops-room-card')}</div><div class="ops-chart-grid">${card('Phân bố thời gian chờ',`<div class="chart-summary"><div><strong>${d.active.length}</strong><span>hồ sơ chưa hoàn tất</span></div><span class="quiet-pill">${icon('clock')} Ngưỡng theo dõi: 30 phút</span></div>${operationalWaitChart()}<div class="chart-caption">${icon('info')} Tổng hợp theo thời gian chờ đã ghi nhận trong từng hồ sơ.</div>`,moreLink('patients','Danh sách'),'traffic-card')}${card('Trạng thái lượt khám',operationalDonut()+`<div class="donut-footer"><span>${icon('check')} Tỷ lệ hoàn tất</span><strong>${donePercent}%</strong></div>`,'','status-card')}</div><div class="ops-bottom-grid">${card('Hoạt động gần đây',recentActivity(),moreLink('logs','Xem nhật ký'))}<section class="card ops-tools"><div class="card-head"><h2>Công cụ điều phối</h2></div><div class="card-body"><div class="workspace-shortcuts">${[['ai','spark','Gợi ý điều phối',`${d.pending.length} hồ sơ chưa có quyết định`,'purple'],['simulation','chart','Mô phỏng vận hành','So sánh phương án phân bổ nguồn lực',''],['wizard','wand','Đánh giá phương pháp','Hỗ trợ chọn cách tiếp cận phù hợp','teal']].map(([a,i,t,s,c])=>`<button data-action="${a}">${circle(i,c)}<span><strong>${t}</strong><small>${s}</small></span>${icon('chevron')}</button>`).join('')}</div><button class="ops-about" data-action="system-info">${icon('info')} Thông tin hệ thống ${icon('chevron')}</button></div></section></div>`;}
function operationalSystemInfo(){modal('Thông tin hệ thống',`<div class="modal-body system-info"><div class="flex">${circle('hospital')}<div><h2>Smart OPD</h2><p>Quản lý và điều phối khám ngoại trú · Phiên bản 2.1</p></div></div><dl><div><dt>Lưu trữ</dt><dd>Dữ liệu được lưu trên trình duyệt hiện tại, chưa đồng bộ giữa các thiết bị.</dd></div><div><dt>Tài khoản và vai trò</dt><dd>Chuyển vai trò hiện điều khiển giao diện. Xác thực và phân quyền phía máy chủ chưa được kết nối.</dd></div><div><dt>Gợi ý điều phối</dt><dd>Sử dụng quy tắc có sẵn; chưa tích hợp mô hình AI hoặc kết nối HIS.</dd></div><div><dt>Mô phỏng và đánh giá</dt><dd>Dùng mô hình tính toán và quy tắc đánh giá tham khảo, chưa hiệu chỉnh bằng dữ liệu bệnh viện thực tế.</dd></div><div><dt>Nguồn dữ liệu</dt><dd>Hồ sơ khởi tạo là dữ liệu giả lập. Các chỉ số trên tổng quan được tính từ danh sách hồ sơ hiện có.</dd></div></dl><p>Không sử dụng thông tin bệnh nhân thật trong phiên bản hiện tại.</p></div>`);}
function operationalExport(){const d=operationalData();download('smart-opd-bao-cao.csv',[['Smart OPD','Báo cáo điều phối ngoại trú'],['Ngày hồ sơ','14/10/2026'],['Tổng lượt tiếp nhận',d.total],['Đã hoàn tất',d.finished.length],['Đang xử lý',d.active.length],['Thời gian chờ trung bình (phút)',d.average],['Chờ trên 30 phút',d.overdue.length],[],['Phòng chức năng','Hồ sơ đang xử lý','Đang chờ','Thời gian chờ TB'],...d.rooms.map(r=>[r.name,r.count,r.waiting,r.average])]);}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.action==='system-info'){e.preventDefault();e.stopImmediatePropagation();operationalSystemInfo();return;}if(el.dataset.action==='export-dashboard'){e.preventDefault();e.stopImmediatePropagation();operationalExport();return;}if(el.dataset.ops||el.dataset.opsDept){e.preventDefault();e.stopImmediatePropagation();state.search='';state.status='Tất cả';state.dept='Tất cả';state.priority='Tất cả';state.pageNumber=1;ui.quick='';if(el.dataset.ops==='finished')state.status='Hoàn tất';if(el.dataset.ops==='overdue')ui.quick='long';if(el.dataset.ops==='attention')ui.quick='dispatch';if(el.dataset.opsDept)state.dept=el.dataset.opsDept;navigate('patients');}},true);
